ALTER TABLE publish_captures ADD COLUMN environment TEXT NOT NULL DEFAULT 'preview' CHECK(environment IN ('preview','production'));
CREATE TRIGGER capture_environment_immutable BEFORE UPDATE OF environment ON publish_captures WHEN NEW.environment IS NOT OLD.environment BEGIN SELECT RAISE(ABORT, 'Capture environment is immutable'); END;
-- One durable activation attempt per capture. An unresolved attempt owns the
-- preview slot indefinitely: a timeout is not evidence that Cloudflare rejected it.
CREATE TABLE public_deployments ( capture_id TEXT PRIMARY KEY REFERENCES publish_captures(id), target TEXT NOT NULL DEFAULT 'publish' CHECK(target = 'publish'), version_id TEXT NOT NULL UNIQUE CHECK(length(version_id) = 36), previous_version_id TEXT NOT NULL CHECK(length(previous_version_id) = 36 AND previous_version_id != version_id), run_id INTEGER NOT NULL REFERENCES build_dispatches(run_id), bundle_sha256 TEXT NOT NULL CHECK(length(bundle_sha256) = 64 AND bundle_sha256 NOT GLOB '*[^0-9a-f]*'), status TEXT NOT NULL DEFAULT 'activating' CHECK(status IN ('activating','uncertain','deployed','rejected')), deployment_id TEXT UNIQUE CHECK(deployment_id IS NULL OR length(deployment_id) = 36), requested_at TEXT NOT NULL, updated_at TEXT NOT NULL CHECK(updated_at >= requested_at), requested_by TEXT NOT NULL, updated_by TEXT NOT NULL, CHECK((status = 'deployed' AND deployment_id IS NOT NULL) OR (status != 'deployed' AND deployment_id IS NULL)) );
CREATE UNIQUE INDEX public_deployment_fence ON public_deployments(target) WHERE status IN ('activating','uncertain');
CREATE INDEX public_deployments_run_id ON public_deployments(run_id);
CREATE TRIGGER public_deployment_ready BEFORE INSERT ON public_deployments WHEN NOT EXISTS ( SELECT 1 FROM publish_captures c JOIN build_dispatches b ON b.capture_id = c.id WHERE c.id = NEW.capture_id AND c.purpose = 'publish' AND c.status = 'ready' AND c.expires_at > NEW.requested_at AND b.status = 'queued' AND b.run_id = NEW.run_id ) BEGIN SELECT RAISE(ABORT, 'Public capture is not ready'); END;
CREATE TRIGGER public_deployment_order BEFORE INSERT ON public_deployments WHEN EXISTS ( SELECT 1 FROM public_deployments d JOIN publish_captures c ON c.id = d.capture_id JOIN publish_captures candidate ON candidate.id = NEW.capture_id WHERE d.status = 'deployed' AND (c.sequence >= candidate.sequence OR c.revision > candidate.revision) ) BEGIN SELECT RAISE(ABORT, 'Public deployment would regress'); END;
CREATE TRIGGER public_deployment_initial BEFORE INSERT ON public_deployments WHEN NEW.status != 'activating' BEGIN SELECT RAISE(ABORT, 'Invalid initial preview state'); END;
CREATE TRIGGER public_deployment_immutable BEFORE UPDATE ON public_deployments WHEN NEW.capture_id IS NOT OLD.capture_id OR NEW.target IS NOT OLD.target OR NEW.version_id IS NOT OLD.version_id OR NEW.previous_version_id IS NOT OLD.previous_version_id OR NEW.run_id IS NOT OLD.run_id OR NEW.bundle_sha256 IS NOT OLD.bundle_sha256 OR NEW.requested_at IS NOT OLD.requested_at OR NEW.requested_by IS NOT OLD.requested_by OR (OLD.deployment_id IS NOT NULL AND NEW.deployment_id IS NOT OLD.deployment_id) BEGIN SELECT RAISE(ABORT, 'Public deployment identity is immutable'); END;
CREATE TRIGGER public_deployment_transition BEFORE UPDATE OF status ON public_deployments WHEN NEW.status != OLD.status AND NOT ( (OLD.status = 'activating' AND NEW.status IN ('uncertain','deployed','rejected')) OR (OLD.status = 'uncertain' AND NEW.status = 'deployed') ) BEGIN SELECT RAISE(ABORT, 'Invalid preview deployment transition'); END;
CREATE TRIGGER public_deployment_audit_insert AFTER INSERT ON public_deployments BEGIN INSERT INTO audit_log(actor,action,entity,created_at) VALUES(NEW.requested_by,'publish.public.activating','capture:' || NEW.capture_id,NEW.requested_at); END;
CREATE TRIGGER public_deployment_audit_update AFTER UPDATE OF status ON public_deployments WHEN NEW.status != OLD.status BEGIN INSERT INTO audit_log(actor,action,entity,created_at) VALUES(NEW.updated_by,'publish.public.' || NEW.status,'capture:' || NEW.capture_id,NEW.updated_at); END;
CREATE TRIGGER public_deployment_no_delete BEFORE DELETE ON public_deployments BEGIN SELECT RAISE(ABORT, 'Public deployment history is retained'); END;

CREATE TABLE publications ( capture_id TEXT PRIMARY KEY REFERENCES publish_captures(id), status TEXT NOT NULL DEFAULT 'queued' CHECK(status IN ('queued','published','failed','expired','superseded')), requested_at TEXT NOT NULL, updated_at TEXT NOT NULL CHECK(updated_at >= requested_at), requested_by TEXT NOT NULL, updated_by TEXT NOT NULL );
CREATE INDEX publications_pending ON publications(status,requested_at);
CREATE TRIGGER publication_ready BEFORE INSERT ON publications WHEN NEW.status != 'queued' OR NOT EXISTS (SELECT 1 FROM publish_captures WHERE id = NEW.capture_id AND purpose = 'publish' AND status = 'ready' AND expires_at > NEW.requested_at) BEGIN SELECT RAISE(ABORT, 'Publication input is not ready'); END;
CREATE TRIGGER publication_identity BEFORE UPDATE ON publications WHEN NEW.capture_id IS NOT OLD.capture_id OR NEW.requested_at IS NOT OLD.requested_at OR NEW.requested_by IS NOT OLD.requested_by OR OLD.status != 'queued' BEGIN SELECT RAISE(ABORT, 'Publication is immutable'); END;
CREATE TRIGGER publication_audit_insert AFTER INSERT ON publications BEGIN INSERT INTO audit_log(actor,action,entity,created_at) VALUES(NEW.requested_by,'publish.requested','capture:' || NEW.capture_id,NEW.requested_at); END;
CREATE TRIGGER publication_audit_update AFTER UPDATE OF status ON publications WHEN NEW.status != OLD.status BEGIN INSERT INTO audit_log(actor,action,entity,created_at) VALUES(NEW.updated_by,'publish.' || NEW.status,'capture:' || NEW.capture_id,NEW.updated_at); END;
CREATE TRIGGER publication_no_delete BEFORE DELETE ON publications BEGIN SELECT RAISE(ABORT, 'Publication history is retained'); END;
